public protocol FsyncEngineProtocol: AnyObject, Sendable {
    
    func cancel(transferId: UInt64) throws 
    
    func clear(keepPinned: Bool) throws 
    
    func confirmTrustReset(resetId: String) throws  -> AccountState
    
    func declineTrustReset(resetId: String) throws 
    
    func delete(itemId: String) throws 
    
    func devices()  -> [Device]
    
    func ensureAccount() throws  -> AccountState
    
    func fetchFileTo(itemId: String, fileId: UInt32, destDir: String) throws  -> UInt64
    
    func fetchRep(itemId: String, idx: UInt32) throws  -> Data
    
    func history(query: String?, cursor: String?, limit: UInt32) throws  -> HistoryPage
    
    func loginStart(email: String) throws 
    
    func loginVerify(email: String, code: String) throws  -> SessionTokens
    
    func logout() throws 
    
    /**
     * `logout` that says whether the backend settled the revocation: `true` = revoked, already
     * dead or refused for good (drop your pending revoke); `false` = only queued in memory, or
     * no session was held (keep the refresh token, retry with `revoke_session` at next launch).
     */
    func logoutConfirmed() throws  -> Bool
    
    func nodeId()  -> String
    
    func pairingCancel() throws 
    
    func pairingConfirm(requestId: UInt64, accept: Bool) throws 
    
    func pairingJoin(input: String) throws  -> PairingPeer
    
    func pairingOffer(mode: PairingMode) throws  -> PairingOffer
    
    func pendingTrustResets()  -> [TrustResetInfo]
    
    func pin(itemId: String, pinned: Bool) throws 
    
    func publishClip(clip: LocalClip) throws  -> Published
    
    func readFileRange(itemId: String, fileId: UInt32, offset: UInt64, len: UInt32) throws  -> Data
    
    func removeDevice(nodeId: String) throws 
    
    /**
     * Re-creates the account's root with this device only. `ReauthRequired`: re-run the OTP.
     */
    func resetAccountTrust() throws  -> AccountState
    
    func sendFiles(nodeId: String, paths: [String]) throws  -> UInt64
    
    func setSession(tokens: SessionTokens) throws 
    
    func setSettings(settings: Settings) throws 
    
    func settings() throws  -> Settings
    
    func start() throws 
    
    func stop() throws 
    
}
