public struct ClipItem {
    public var itemId: String
    public var from: String
    public var fromName: String
    public var kind: ClipKind
    public var tsMs: UInt64
    public var preview: String?
    public var reps: [RepInfo]
    public var files: [FileInfo]
    public var totalSize: UInt64
    public var push: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(itemId: String, from: String, fromName: String, kind: ClipKind, tsMs: UInt64, preview: String?, reps: [RepInfo], files: [FileInfo], totalSize: UInt64, push: Bool) {
        self.itemId = itemId
        self.from = from
        self.fromName = fromName
        self.kind = kind
        self.tsMs = tsMs
        self.preview = preview
        self.reps = reps
        self.files = files
        self.totalSize = totalSize
        self.push = push
    }
}

#if compiler(>=6)
extension ClipItem: Sendable {}
#endif


extension ClipItem: Equatable, Hashable {
    public static func ==(lhs: ClipItem, rhs: ClipItem) -> Bool {
        if lhs.itemId != rhs.itemId {
            return false
        }
        if lhs.from != rhs.from {
            return false
        }
        if lhs.fromName != rhs.fromName {
            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.tsMs != rhs.tsMs {
            return false
        }
        if lhs.preview != rhs.preview {
            return false
        }
        if lhs.reps != rhs.reps {
            return false
        }
        if lhs.files != rhs.files {
            return false
        }
        if lhs.totalSize != rhs.totalSize {
            return false
        }
        if lhs.push != rhs.push {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(itemId)
        hasher.combine(from)
        hasher.combine(fromName)
        hasher.combine(kind)
        hasher.combine(tsMs)
        hasher.combine(preview)
        hasher.combine(reps)
        hasher.combine(files)
        hasher.combine(totalSize)
        hasher.combine(push)
    }
}



