public enum AccountEvent {
    
    case listAdvanced(seq: UInt64
    )
    case selfRemoved
    case trustReset(resetId: String, devices: UInt32, deviceNames: [String]
    )
    case historyReset(backup: String
    )
    case sessionExpired
}


#if compiler(>=6)
extension AccountEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccountEvent: FfiConverterRustBuffer {
    typealias SwiftType = AccountEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .listAdvanced(seq: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .selfRemoved
        
        case 3: return .trustReset(resetId: try FfiConverterString.read(from: &buf), devices: try FfiConverterUInt32.read(from: &buf), deviceNames: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 4: return .historyReset(backup: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .sessionExpired
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AccountEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .listAdvanced(seq):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(seq, into: &buf)
            
        
        case .selfRemoved:
            writeInt(&buf, Int32(2))
        
        
        case let .trustReset(resetId,devices,deviceNames):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(resetId, into: &buf)
            FfiConverterUInt32.write(devices, into: &buf)
            FfiConverterSequenceString.write(deviceNames, into: &buf)
            
        
        case let .historyReset(backup):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(backup, into: &buf)
            
        
        case .sessionExpired:
            writeInt(&buf, Int32(5))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccountEvent_lift(_ buf: RustBuffer) throws -> AccountEvent {
